def num_distinct(s, t):
    def f(i, j):               # ways s[:i] contains t[:j]
        if j == 0:
            return 1
        if i == 0:
            return 0
        ways = f(i - 1, j)
        if s[i - 1] == t[j - 1]:
            ways += f(i - 1, j - 1)
        return ways
    return f(len(s), len(t))

