def num_distinct(s, t):
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = 1
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i - 1][j]
            if s[i - 1] == t[j - 1]:
                dp[i][j] += dp[i - 1][j - 1]
    return dp[m][n]

def num_distinct(s, t):
    prev = [1] + [0] * len(t)
    for ch in s:
        cur = prev[:]
        for j in range(1, len(t) + 1):
            if t[j - 1] == ch:
                cur[j] += prev[j - 1]
        prev = cur
    return prev[-1]

def num_distinct(s, t):
    ways = [1] + [0] * len(t)
    for ch in s:
        for j in range(len(t), 0, -1):
            if t[j - 1] == ch:
                ways[j] += ways[j - 1]
    return ways[-1]
